"""Правила сопоставления категорий с номенклатурой поставщика в 1С."""
import re

def pole_categories(row):
    name = re.sub(r'\s+', ' ', row['item'].lower().replace('ё', 'е').replace('–', '-')).strip()
    text = name + ' ' + str(row.get('full_name') or '').lower()
    pole = bool(re.match(r'^(?:(?:[а-я]+-)*[а-я]*(?:ая|яя|ые|ие|ый|ой|ей|ное|ная|ое|ее)\s+){0,5}опор(?:а|ы)\b|^опор\.', name))
    column = bool(re.match(r'^стойк[аи]?\b', name))
    if not (pole or column):
        return {}
    if re.search(r'^(?:жесткая анкерная линия|к-т|комплект|свая|сваи|трубная продукция|устройств|металлоконструкц|фундамент|траверс|хомут|болт|заземл|установк)', name):
        return {}
    if re.search(r'деревян|освещ|прожектор|антенн|подвижн|неподвижн|скользящ|трубопровод|газоанализ|опора хомутов|опора вертикальная сн|опора от-|под (?:блок|разъедин|ои\b)|пкпо', name):
        return {}
    energy = bool(re.search(
        r'лэп|\bвл[из]?\b|\bсв\s*[-]?\s*(?:95|105|110|164)\b|\bснв\s*7[- ]13\b|\bск\s*22[.,]|'
        r'\b[1-4]?(?:пб|пс|пгс|ппм|пм|ум|аум|ус|ув|пв|п|у)\s*(?:35|110|220|330|500)|'
        r'25\.0074|22\.0028|21\.0112|3\.407', text))
    if not energy:
        return {}
    if re.search(r'железобетон|\bж\s*/?\s*б\b|\bсв\s*[-]?\s*(?:95|105|110|164)\b|\bснв\s*7[- ]13\b|\bск\s*22[.,]', text):
        return {'Опоры ЛЭП (ЖБИ)': ('Прямое', 'Железобетон указан в наименовании или подтверждённой серии стойки')}
    if re.search(r'метал(?:л)?ическ|стальн|\bст\.|09г2с|\bс345|оцинк|многогран|решетчат|металлоконструкц', text + ' ' + row.get('group', '').lower()):
        return {'Опоры ЛЭП (мет.)': ('Прямое', 'Стальное исполнение указано в наименовании или группе номенклатуры')}
    if re.search(r'25\.0074|22\.0028|3\.407\.2|3\.407\.9-180|\b[1-4]?(?:ппм|аум|пгс|пм|ум|ус|ув|пв|пс|пп|п|у)\s*[-]?\s*(?:35|110|220|330|500)(?!\d)', text):
        return {'Опоры ЛЭП (мет.)': ('Прямое', 'Подтверждённая серия или типовая марка стальной опоры ЛЭП')}
    if re.search(r'\b(?:2?ас|уас|пас|пуас|аос|паос)\s*10-\d', text):
        return {'Опоры ЛЭП (мет.)': ('Прямое', 'Марка стальной трубчатой опоры серии 25.0074 по каталогу производителя')}
    if re.search(r'\b[12]?(?:асо|аусо|ас|аус|пс|пус)(?:10|35)пи-', text):
        return {'Опоры ЛЭП (мет.)': ('Прямое', 'Марка стальной опоры из гнутого профиля серий ЭЛ-ТП')}
    # Марки без номера проекта ПС10 и АС10 встречаются в разных исполнениях.
    # Само обозначение напряжения не определяет материал.
    return {}


CATEGORIES = ["Опоры ЛЭП (ЖБИ)","Опоры ЛЭП (мет.)","Мачты освещения","Фундаменты ЛЭП","Резервуары","Ёмкости","Сэндвич-панели","Проволока","Кабель","Изоляторы","Металлопрокат","Профнастил","ЛКМ","Модульные здания","Эстакады","Ограждения и ворота","ЖБИ","Изготовление МК","Автоперевозки","Негабаритные перевозки","Ж/Д перевозки","Мультимодальные перевозки","Спецтехника","Экспедирование","Складские услуги"]


def norm(text):
    return re.sub(r"\s+", " ", str(text).lower().replace("ё","е").replace("–","-").replace("—","-")).strip()


def classify(row):
    name = norm(row["item"])
    group = norm(row["group"])
    matches = {}
    def hit(category, pattern, exclude=None, possible=False, reason=None):
        if re.search(pattern,name) and not (exclude and re.search(exclude,name)):
            matches[category] = ("Уточнить" if possible else "Прямое", reason or "Номенклатура соответствует категории")
    hit("Мачты освещения",r"мачт[а-я]*.*(?:освещ|прожектор)|(?:освещ|прожектор).*мачт|высокомачтовая опора",
        r"(?:комплект.*(?:монтаж|креплен)|ростверк|болт|фундамент|рубильник|трансформатор|антенн|вентиляц|связи)")
    hit("Фундаменты ЛЭП",r"\bфундамент\b.*(?:лэп|\bвл\b|3\.407|\bф\d)|\bподножник\b.*(?:опор|3\.407|ф\d)",r"(?:болт|анкер|рама|блок.*болт|закладн|добавка)")
    hit("Фундаменты ЛЭП",r"\bфундамент\b",r"(?:болт|анкер|рама|закладн|3\.407|\bф\d|лэп|\bвл\b)",True,"Фундамент указан, применение для ЛЭП требует подтверждения")
    hit("Резервуары",r"(?:^|\b)(?:резервуар(?:\s|$)|рвс\s*[-v=]?\s*\d|ргс[пн]?\s*[-]?\s*\d)",r"(?:монтаж|защит|затвор|понтон|клапан|пожаротуш|лестниц|систем|крыш|м/к|металлоконструкц|проект|молниеотвод|площадк)")
    hit("Ёмкости",r"\bемкост(?:ь|и|ной|ная)\b|\bбак\b.*(?:вод|топлив|нефт|бензин|сталь|м3|м\^3)",r"(?:аккумулятор|батаре|датчик|кабел|емкост.*(?:ач|а\*|а×|фарад)|для емкост|люк|крышк|насос|патрубок|комплект.*емкост)")
    hit("Сэндвич-панели",r"(?:сэндвич|сендвич)|панел[а-я]* трехслойн",r"(?:саморез|захват|креплен|ворота|отлив|уплотн|нащельник|комплект.*монтаж)")
    hit("Проволока",r"\bпроволок(?:а|и|у|ой|е)\b",r"(?:кабел|из.*проволок|щетк|корщ|мат теплоизол|прошит|шланг|сетка.*проволок)")
    if "Проволока" not in matches:
        hit("Проволока",r"^(?:трос|канат)\b",possible=True,reason="В номенклатуре трос/канат, требуется подтвердить ассортимент проволоки")
    cable_accessory = r"(?:лоток|короб|муфт|наконечник|стяжк|ввод|маркер|бирк|кабельканал|кабель-канал|полк|держател|креплен|клемм|труб|опор|кронштейн|профил|зажим|блок|щит|шкаф|соединитель|крышк|заглушк|скоб|хомут|клипс|сальник|изолятор|приставк|гильз|лестниц)"
    hit("Кабель",r"^(?:кабел[ья]|провод(?:\s|$))|\b(?:кабель силовой|кабель контрольный|провод сип|провод ас)\b",cable_accessory)
    if "Кабель" not in matches and re.search(r"кабели|провода|провод (?:ас|сип|пу|нв|пв)|кг-хл|кип|кпс|кввг|мкш|ввг",group) and not re.search(cable_accessory,name):
        matches["Кабель"] = ("Прямое","Номенклатура в кабельной/проводной группе 1С")
    hit("Изоляторы",r"^изолятор(?:\s|$)",r"(?:короткого замыкан|для наконечник|разветвит|2p[a-z]|2р[а-я])")
    hit("Металлопрокат",r"^(?:лист|труба|круг|полоса|уголок|швеллер|двутавр|квадрат|арматура)\b.*(?:сталь|стальн|ст\.?\s?3|09г2с|12х18|оцинк|электросвар|профильн|а500|а400|а240|а-iii|а-iii|г/к|х/к|горячекат|холоднокат|гост (?:8509|8240|2590|2591|10704|10705|8732|8734|3262|19903|19904|103|5781|34028))|^металлопрокат\b|^закупка металлопроката",
        r"(?:пнд|пвх|полипроп|полиэтил|металлопласт|резин|трубопроводн.*арматур|по чертеж|осветител)")
    hit("Металлопрокат",r"^(?:швеллер|двутавр|уголок)\s+[\d№]|^лист\s+рифлен",r"(?:пвх|пластик|алюмин.*декор)")
    hit("Профнастил",r"\bпрофнастил\b|\bпрофлист\b|^лист профилированн",r"(?:саморез|креплен|кронштейн|уплотн)")
    hit("ЛКМ",r"^(?:грунт(?:овка|-эмаль)|эмаль|краска|лак\b|лакокрас|грунт\s+эпоксид|грунт\s+гф[- ]|гф[- ]?021|пф[- ]?115)",r"(?:краскопульт|грунтовка.*(?:бетоноконтакт|акрилов.*глубок))")
    hit("Модульные здания",r"\bмодульн[а-я]* (?:здан|сооруж|столов|офис)|\bблок[- ]контейнер\b|\bвагон[- ]дом\b|\bбытовк|столовая модульного типа",r"(?:насос|трансформатор|котельн.*модуль|м/к|металлоконструкц|датчик|контейнер.*мусор)")
    hit("Эстакады",r"^(?:досмотровая |технологическая |кабельная )?эстакада\b|\bизготовление.*эстакад",r"(?:защит|для эстакад|лоток|фундамент|опор|огражден)")
    hit("Ограждения и ворота",r"^(?:панель ограждения|ограждение|барьерное ограждение|изделие ограждение|секция ограждения|калитка|ворота|промышленные.*ворота|забор\b)|\b(?:3d|3д)[- ]огражден",r"(?:замок|привод|петля|колес|для ворот|доводчик|пульт|креплен|ключ|заглушк)")
    if "Ограждения и ворота" not in matches:
        hit("Ограждения и ворота",r"^сетка\s+(?:рабица|манье|сварная)|колючая проволока|армированная колючая|спиральн.*барьер",possible=True,reason="Материал/компонент ограждения, готовые ограждения и ворота требуют подтверждения")
    hit("ЖБИ",r"^(?:балка|плита|блок|свая|стойка|опора|фундамент|кольцо|лоток|перемычка|подножник|панель).*?(?:железобетон|\bж/?б\b|бетонн|\bжби\b)|^(?:плита|стойка|свая)\s+(?:паг|пдн|пдп|св[- ]?\d)|\bфундамент\s+ф\d.*3\.407",r"(?:болт|накладк|хомут|для креплен|подвижн|на железобетонн|для железобетонн|металлическ|стальная)")
    hit("Изготовление МК",r"изготовлен[а-я]*.*(?:металлоконструкц|\bмк\b|м/к)|разработк.*кмд.*изготовлен",r"(?:требования на изготовление)")
    if "Изготовление МК" not in matches:
        hit("Изготовление МК",r"металлоконструкц|\bм/к\b|^мк\b",possible=True,reason="Есть металлоконструкции, собственное изготовление требует подтверждения")
    hit("Автоперевозки",r"автодоставк|автотранспорт|автоперевоз|перевозке груза вездеходным|транспортн.*(?:машина \d|а/м\s)|доставк.*машина \d",r"(?:грунт|эмаль|азс|краска|контейнерная азс)")
    hit("Негабаритные перевозки",r"(?:негабарит|крупногабарит).*(?:перевоз|достав)|(?:перевоз|достав).*негабарит|аренда.*трала")
    hit("Ж/Д перевозки",r"(?:перевоз|достав|тариф|услуг).*(?:ж/?д\b|железнодорожн)|(?:ж/?д\b|железнодорожн).*(?:перевоз|достав|тариф)")
    hit("Мультимодальные перевозки",r"мультимодаль|интермодаль|смешанн.*перевоз")
    hit("Спецтехника",r"(?:услуг|аренда|работ).*(?:автокран|экскаватор|погрузчик|манипулятор|вездеход|спецтехник)|(?:автокран|экскаватор|погрузчик|манипулятор|спецтехник).*(?:услуг|аренда)",r"(?:ложемент|запчаст|захват)")
    hit("Экспедирование",r"транспортно\s*-?\s*экспедиц|экспедирован",r"возмещение страхования")
    hit("Складские услуги",r"^услуги хранения|ответственн.*хранени|складск.*услуг|аренда склад|хранени.*(?:груза|товара)",r"(?:контейнер|вагон|здание|м/к|козин|корзин|емкость|стеллаж|вешалк)")
    matches.update(pole_categories(row))
    return {k: v for k, v in matches.items() if v[0] == "Прямое"}
